<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';import {useEditor} from '../stores/editor';import {referencedAssets} from '../storage/archive';import {prepareEnvironment} from '../assets/hdri';import {uid} from '../domain/project';
const e=useEditor(),busy=ref(false),error=ref('');let controller:AbortController|undefined;
const maps=computed(()=>{const ids=referencedAssets(e.document);return e.assets.filter(a=>a.kind==='hdri'&&ids.has(a.id));});
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const projectId=e.document.id;controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{await prepareEnvironment(file,64,controller.signal);if(e.document.id!==projectId||controller.signal.aborted)return;const id=uid();await e.addAsset({id,name:file.name,kind:'hdri',originals:[{name:file.name,blob:file}],warnings:[]});if(e.document.id!==projectId)return;e.edit('Выбрать HDRI',p=>p.lighting.hdriAssetId=id);}catch(reason){if((reason as Error).name!=='AbortError')error.value=(reason as Error).message;}finally{busy.value=false;input.value='';}}
watch(()=>e.document.id,()=>controller?.abort());
onBeforeUnmount(()=>controller?.abort());
</script>
<template><h3>HDRI — свет окружения</h3><p class="hint">Панорама Radiance .hdr, 2:1, до 8 Мп и 64 МБ. На качестве 1 отключена; 2–5 используют уменьшенную карту для освещения и отражений.</p><label>Добавить HDRI<input type="file" accept=".hdr" :disabled="busy" @change="upload"></label><p v-if="busy" role="status">Подготовка HDRI… <button @click="controller?.abort()">Отменить</button></p><p v-if="error" class="warnings" role="alert">{{error}}</p><label>Карта окружения<select :value="e.document.lighting.hdriAssetId??''" @change="e.edit('Карта окружения',p=>{p.lighting.hdriAssetId=($event.target as HTMLSelectElement).value||undefined})"><option value="">Без HDRI</option><option v-for="map in maps" :value="map.id">{{map.name}}</option></select></label><label v-if="e.document.lighting.hdriAssetId">Яркость HDRI<input type="number" min="0" max="10" step=".1" :value="e.document.lighting.hdriIntensity??1" @change="e.edit('Яркость HDRI',p=>{p.lighting.hdriIntensity=Number(($event.target as HTMLInputElement).value)})"></label></template>
